import{_ as a,o as t,c as i,a5 as r}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Caption text moderation","description":"","frontmatter":{},"headers":[],"relativePath":"feature/caption-text-moderation/spec.md","filePath":"feature/caption-text-moderation/spec.md"}'),n={name:"feature/caption-text-moderation/spec.md"};function o(s,e,c,l,d,u){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="caption-text-moderation" tabindex="-1">Caption text moderation <a class="header-anchor" href="#caption-text-moderation" aria-label="Permalink to &quot;Caption text moderation&quot;">​</a></h1><h2 id="objective-and-user-story" tabindex="-1">Objective and user story <a class="header-anchor" href="#objective-and-user-story" aria-label="Permalink to &quot;Objective and user story&quot;">​</a></h2><p>Creators check generated or manually written captions before using them. Use the existing server-side DEPLOY_ACCESS_KEY for a dedicated text classification API, independently of DEPLOY_API_KEY used for generation.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Generated editor captions include moderation; Creator can recheck edited captions and check the Content Writing draft explicitly.</li><li>Results are PASSED, WARNING, BLOCKED, or NOT_CHECKED. Level 3 harmful content blocks using the generated caption; level 1/2 and profanity/PII request review. Commercial promotions and phone numbers alone do not block marketing captions.</li><li>Changing text invalidates the visible verdict. A delayed response cannot label newer text as checked.</li><li>Missing configuration, provider errors, unsupported languages, empty/malformed responses never produce PASSED.</li><li>Key stays in AI-service environment, never browser, logs, tracked files, or business-service responses. Dedicated moderation uses its configured Secret Key; it does not automatically fall back to the generation credential.</li><li>At most 8,000 characters; split into overlapping &lt;=1,024 UTF-16-unit segments without splitting surrogate pairs; check all segments.</li><li>Text moderation is advisory and not legal compliance or a replacement for publish-time authorization. No automatic admin sanctions.</li></ul><h2 id="api-contract-and-errors" tabindex="-1">API contract and errors <a class="header-anchor" href="#api-contract-and-errors" aria-label="Permalink to &quot;API contract and errors&quot;">​</a></h2><p>Internal POST /api/v1/ai/content/moderate takes {text}; X-Internal-Key required. Workspace POST /api/v1/workspaces/{workspaceId}/ai/captions/moderate checks existing membership/AI access. Result {status,issues:[{code,message,excerpt}]} uses fixed application messages, not provider error text. Provider contract: Hive documented V3 Text Moderation API, Authorization Bearer; DEPLOY_ACCESS_KEY contains the Secret Key, not the Access Key ID. The user explicitly authorized credential transmission to this exact Hive V3 endpoint on 2026-10-28. Follow the Playground contract: JSON input with exactly one text object per call, output classes with class/score (and explicitly validated class_name/value compatibility), and string_matches.</p><h2 id="ui-states-and-i18n" tabindex="-1">UI states and i18n <a class="header-anchor" href="#ui-states-and-i18n" aria-label="Permalink to &quot;UI states and i18n&quot;">​</a></h2><p>editor.moderation: title, check, checking, PASSED, WARNING, BLOCKED, NOT_CHECKED, stale, tooLong, issue labels. Add all keys together to vi/editor.json and en/editor.json. Existing theme tokens and light/dark semantic surfaces; keyboard-accessible button and live status. Show no verdict while checking. Preserve editor text on failure.</p><h2 id="definition-of-done-and-exclusions" tabindex="-1">Definition of done and exclusions <a class="header-anchor" href="#definition-of-done-and-exclusions" aria-label="Permalink to &quot;Definition of done and exclusions&quot;">​</a></h2><p>Mocked provider/auth/error tests, frontend typecheck/build and focused UI verification. No key rotation, server-side publishing enforcement, media moderation, translation or LLM-based moderation fallback. Report successful live verification separately; current key validity can block it.</p><h2 id="editor-typing-and-publish-now-gate-2026-10-28" tabindex="-1">Editor typing and Publish Now gate (2026-10-28) <a class="header-anchor" href="#editor-typing-and-publish-now-gate-2026-10-28" aria-label="Permalink to &quot;Editor typing and Publish Now gate (2026-10-28)&quot;">​</a></h2><ul><li>The main post editor checks caption plus hashtags once after 3 seconds without a text change. Empty text sends no request. Further typing resets the full delay.</li><li>Publish Now cancels the remaining debounce and checks immediately, or joins the identical in-flight request. Only PASSED/WARNING for the exact current text can proceed to saving/publish API; BLOCKED, NOT_CHECKED or transport failure prevents publishing with a translated explanation.</li><li>Reuse a valid verdict only until text/workspace changes. Ignore and cancel obsolete responses. Repeated Publish Now clicks cannot dispatch duplicate checks or publishes. No network call per keystroke.</li><li>Show waiting/checking/verdict inline beneath the main rich text editor; preserve content on failure. Existing task/editor access remains unchanged. This gate covers the Publish Now UI entry point, not a new server-wide publishing policy.</li><li>New parallel vi/en keys: editor.moderation.waiting, publishBlocked, publishUnavailable, changed. Light/dark semantic tokens and narrow layout must remain usable.</li></ul><h2 id="moderation-failure-diagnostics" tabindex="-1">Moderation failure diagnostics <a class="header-anchor" href="#moderation-failure-diagnostics" aria-label="Permalink to &quot;Moderation failure diagnostics&quot;">​</a></h2><p>Provider failures remain NOT_CHECKED. Return fixed issue codes for missing configuration, authentication failure (401), permission denial (403), rate limiting (429), timeout, connection failure and invalid response. Log only reason, exception class and HTTP status, never credentials, URLs, response bodies or caption text. Translate recovery messages in vi/en using existing UI/theme components. Do not fall back to the generation key or bypass checks.</p><h2 id="entity-matches-and-unsupported-categories-correction" tabindex="-1">Entity matches and unsupported categories correction <a class="header-anchor" href="#entity-matches-and-unsupported-categories-correction" aria-label="Permalink to &quot;Entity matches and unsupported categories correction&quot;">​</a></h2><p>Recognized entity-only filters (athlete, celebrity, politician, religious_figure, likeness) are informational, not violations. Preserve profanity, PII, custom and IWF handling. Read string_matches plus documented text_filters/pii_entities arrays conservatively. Harmful categories with -1 identify each unsupported category using fixed translated codes. Partial coverage with valid checked categories is WARNING; all-unsupported or malformed results remain NOT_CHECKED. Retrying does not add language support. Do not loosen Publish Now gate. Secret Key is required for Bearer authentication; Access Key ID is not usable as a bearer credential. Credential values for generation and moderation may be the same when authorized by the provider.</p><h2 id="generic-partial-response-diagnosis" tabindex="-1">Generic partial response diagnosis <a class="header-anchor" href="#generic-partial-response-diagnosis" aria-label="Permalink to &quot;Generic partial response diagnosis&quot;">​</a></h2><p>Record fixed parser diagnostic reasons when a successful provider HTTP response cannot produce a complete verdict. Never infer unsupported language solely from generic partial results.</p><h2 id="class-entry-contract-correction" tabindex="-1">Class entry contract correction <a class="header-anchor" href="#class-entry-contract-correction" aria-label="Permalink to &quot;Class entry contract correction&quot;">​</a></h2><p>Accept consistent class/score and class_name/value class entries. Reject partial/mixed/conflicting aliases; retain unknown-category and unsupported-language handling. No language override, credential change or policy relaxation.</p><h2 id="live-schema-diagnosis" tabindex="-1">Live schema diagnosis <a class="header-anchor" href="#live-schema-diagnosis" aria-label="Permalink to &quot;Live schema diagnosis&quot;">​</a></h2><p>Diagnose live class-entry schema using only allowlisted field names and type names; never serialize values or arbitrary field names.</p><h2 id="observed-v3-class-value-schema" tabindex="-1">Observed V3 class/value schema <a class="header-anchor" href="#observed-v3-class-value-schema" aria-label="Permalink to &quot;Observed V3 class/value schema&quot;">​</a></h2><p>Live V3 at 20:28:58 returned class:str,value:int. Accept class/value as the primary response contract, class/score and class_name/value compatibility. Reject mismatched name/score aliases, nonnumeric severity and unknown-only classifications.</p><h2 id="partial-coverage-policy-reloop-reference" tabindex="-1">Partial coverage policy (ReLoop reference) <a class="header-anchor" href="#partial-coverage-policy-reloop-reference" aria-label="Permalink to &quot;Partial coverage policy (ReLoop reference)&quot;">​</a></h2><p>User requested reference to ReLoop Hive.js. Adopt partial coverage as WARNING, not PASSED, only when at least one harmful category was validly checked and the response is otherwise valid. Retain unsupported_&lt;category&gt; issues. WARNING may proceed through existing editor gate. All unsupported, unsupported language, malformed payloads and transport/auth failures remain NOT_CHECKED and prevent publishing. Verified harmful severity 3/IWF remain BLOCKED. Do not copy ReLoop keyword/mock-safe fallback or confidence thresholds.</p><h2 id="user-requested-unsupported-as-safe-policy" tabindex="-1">User requested unsupported-as-safe policy <a class="header-anchor" href="#user-requested-unsupported-as-safe-policy" aria-label="Permalink to &quot;User requested unsupported-as-safe policy&quot;">​</a></h2><p>User policy: explicit unsupported categories (-1) do not create issues or prevent PASSED. API/transport/malformed failures remain unchecked. Actual detections expose severity score when provided and matching excerpt when available. Server logs may contain detected excerpt and score as explicitly requested, never credentials or full caption. Semantic classifiers without spans must not invent offending words.</p>',29)])])}const m=a(n,[["render",o]]);export{h as __pageData,m as default};
